import { atom, read, update } from 'claude-code'
import type { EngineInterface, HookStream, ProcessSpawnChunk, ProcessSpawnResult, Register } from 'claude-code'

import type { Run } from '../types'

type Engine = EngineInterface
type Stream = HookStream<ProcessSpawnChunk, ProcessSpawnResult>

const MAX_COMMANDS = 6
// The most output kept per run, from its end.
const MAX_OUTPUT = 64_000
// The most output sent to Claude, from its end.
const MAX_SENT = 20_000
const FLUSH_MS = 150
const TICK_MS = 1000

const SHELL_LANGS = new Set(['sh', 'bash', 'zsh', 'shell', 'console', 'terminal', 'shell-session', 'shellsession'])
// These show a session: output under each prompted line, and only the
// prompted lines are commands.
const SESSION_LANGS = new Set(['console', 'terminal', 'shell-session', 'shellsession'])
const FENCE = /^ {0,3}(`{3,}|~{3,})[ \t]*([\w+-]*)[^\n]*\n([\s\S]*?)\n {0,3}\1[ \t]*$/gm
// Claude Code's way of telling the person to run a command themselves.
const BANG = /`! ([^`\n]+)`/g
const PROMPT = /^\s*[$%] /
// The shell prints its pid, then becomes the person's shell running the
// command: in a session of its own where setsid exists, so Stop can end the
// command and everything it started.
const WRAPPER = [
  'printf "\\036%s\\n" "$$" >&2',
  'if command -v setsid >/dev/null 2>&1; then exec setsid "$0" -c "$1"; fi',
  'exec "$0" -c "$1"',
].join('\n')
const PID_LINE = /\x1e(\d+)\n/
const KILL_AFTER_MS = 3000
const ANSI = /\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[@-Z\\-_]/g
const CONTROL = /[\x00-\x08\x0b-\x1f\x7f]/g

const runs = { plugin: 'run-button', key: 'runs' } as const
const tick = atom({ plugin: 'run-button', key: 'tick' } as const, 0)

// The commands running now, by run id, so Stop can end one. A reload of the
// module kills them, and a run left `running` without a stream here is one.
const streams = new Map<string, Stream>()
const pids = new Map<string, number>()
const stopping = new Set<string>()
let isTickPending = false
let maxLines = 15

function commandsOf(text: string): string[] {
  const found: { at: number; command: string }[] = []
  for (const match of text.matchAll(FENCE)) {
    const language = (match[2] ?? '').toLowerCase()
    if (!SHELL_LANGS.has(language)) continue
    const lines = (match[3] ?? '').split('\n')
    if (SESSION_LANGS.has(language)) {
      for (const line of lines) if (PROMPT.test(line)) found.push({ at: match.index, command: line.replace(PROMPT, '') })
      continue
    }
    const filled = lines.filter(line => line.trim() !== '')
    const isPrompted = filled.length > 0 && filled.every(line => PROMPT.test(line))
    found.push({ at: match.index, command: (isPrompted ? lines.map(line => line.replace(PROMPT, '')) : lines).join('\n') })
  }
  for (const match of text.matchAll(BANG)) found.push({ at: match.index, command: match[1] ?? '' })

  const commands = found.sort((a, b) => a.at - b.at).map(one => one.command.trim())
  return [...new Set(commands.filter(command => command !== ''))].slice(0, MAX_COMMANDS)
}

function expandTabs(line: string): string {
  let out = ''
  for (const char of line) out += char === '\t' ? ' '.repeat(8 - (out.length % 8)) : char
  return out
}

// Output as a terminal would leave it on screen: colours dropped, and a
// carriage return redrawing its line (a progress bar ends at its last state).
function linesOf(output: string): string[] {
  const lines = output
    .replace(ANSI, '')
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map(line => expandTabs(line.slice(line.lastIndexOf('\r') + 1)).replace(CONTROL, ''))
  if (lines.at(-1) === '') lines.pop()
  return lines
}

function seconds(ms: number): string {
  const s = Math.max(0, ms) / 1000
  if (s < 10) return `${s.toFixed(1)}s`
  if (s < 60) return `${Math.floor(s)}s`
  return `${Math.floor(s / 60)}m${String(Math.floor(s) % 60).padStart(2, '0')}s`
}

async function hashOf(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return [...new Uint8Array(digest)]
    .slice(0, 6)
    .map(byte => byte.toString(16).padStart(2, '0'))
    .join('')
}

function tickSoon($: Engine): void {
  if (isTickPending) return
  isTickPending = true
  $.clock.after(TICK_MS, () => {
    isTickPending = false
    void update($, tick, n => n + 1)
  })
}

// Runs the command in the person's shell, with no terminal and stdin closed,
// in the session's directory. Output is written to state at most every
// FLUSH_MS, which redraws the reply.
async function start($: Engine, id: string, command: string): Promise<void> {
  if (streams.has(id)) return
  const shell = (await $.env.get('SHELL')) || '/bin/sh'
  const run: Run = { command, status: 'running', output: '', cut: 0, startedAt: await $.clock.now() }
  await $.state.set({ ...runs, id }, run)
  stopping.delete(id)
  const stream = $.process.spawn({
    argv: ['sh', '-c', WRAPPER, shell, command],
    env: { NO_COLOR: '1', PAGER: 'cat', GIT_PAGER: 'cat' },
  })
  streams.set(id, stream)
  void pump($, id, run, stream)
}

async function pump($: Engine, id: string, run: Run, stream: Stream): Promise<void> {
  const ref = { ...runs, id }
  let isFlushPending = false
  try {
    for (;;) {
      const step = await stream.next()
      if (step.done) {
        const result = step.value as ProcessSpawnResult | undefined
        run.status = stopping.has(id) || (result?.signal ?? null) !== null ? 'stopped' : 'done'
        if (typeof result?.code === 'number') run.exitCode = result.code
        break
      }
      let text = step.value.text
      if (step.value.stream === 'stderr' && !pids.has(id)) {
        const marked = PID_LINE.exec(text)
        if (marked !== null) {
          pids.set(id, Number(marked[1]))
          text = text.replace(PID_LINE, '')
        }
      }
      run.output += text
      if (run.output.length > MAX_OUTPUT) {
        const over = run.output.length - MAX_OUTPUT
        const at = run.output.indexOf('\n', over)
        const cutAt = at < 0 ? over : at + 1
        run.cut += cutAt
        run.output = run.output.slice(cutAt)
      }
      if (!isFlushPending) {
        isFlushPending = true
        $.clock.after(FLUSH_MS, () => {
          isFlushPending = false
          if (run.status === 'running') void $.state.set(ref, { ...run })
        })
      }
    }
  } catch (error) {
    if (stopping.has(id)) {
      run.status = 'stopped'
    } else {
      run.status = 'failed'
      run.error = error instanceof Error ? error.message : String(error)
    }
  } finally {
    streams.delete(id)
    pids.delete(id)
    stopping.delete(id)
    run.endedAt = await $.clock.now()
    await $.state.set(ref, { ...run })
  }
}

async function kill($: Engine, pid: number, signal: string): Promise<void> {
  // The group first; a command started without setsid has none of its own.
  await $.process.run(['kill', `-${signal}`, '--', `-${pid}`]).catch(() => undefined)
  await $.process.run(['kill', `-${signal}`, String(pid)]).catch(() => undefined)
}

async function stop($: Engine, id: string): Promise<void> {
  const stream = streams.get(id)
  if (stream === undefined) return
  stopping.add(id)
  const pid = pids.get(id)
  if (pid === undefined) {
    void stream.return({ code: null, signal: 'SIGTERM' }).catch(() => undefined)
    return
  }
  await kill($, pid, 'TERM')
  $.clock.after(KILL_AFTER_MS, () => {
    if (streams.has(id) && pids.get(id) === pid) void kill($, pid, 'KILL')
  })
}

// The model reads the row on its next request; the person never sees it as
// typed, so the button turns into a note once it is sent.
async function send($: Engine, id: string): Promise<void> {
  const ref = { ...runs, id }
  const { value: run } = await $.state.get(ref)
  if (run === undefined || run.status === 'running' || run.isSent === true) return

  let output = linesOf(run.output).join('\n')
  const isCut = run.cut > 0 || output.length > MAX_SENT
  if (output.length > MAX_SENT) output = output.slice(-MAX_SENT)
  const took = seconds((run.endedAt ?? run.startedAt) - run.startedAt)
  const ending =
    run.status === 'stopped'
      ? `I stopped it after ${took}.`
      : run.status === 'failed'
        ? `It could not run: ${run.error ?? 'unknown error'}.`
        : `It exited with code ${run.exitCode ?? '?'} after ${took}.`
  const text = [
    'I ran this command myself, with the Run button under your reply:',
    '```sh',
    run.command,
    '```',
    ending,
    output === '' ? 'It wrote no output.' : `${isCut ? 'The end of its output' : 'Its output'}:\n\`\`\`\n${output}\n\`\`\``,
  ].join('\n')

  const sent = await $.session.append({ message: { type: 'user', content: [{ type: 'text', text }] } })
  if ('deny' in sent && typeof sent.deny === 'string') {
    $.ui.toast(`run-button: could not send the output: ${sent.deny}`)
    return
  }
  await update($, { ...runs, id }, held => ({ ...(held ?? run), isSent: true }))
  $.ui.toast('Sent the output to Claude. It reads it with your next message.')
}

export const register: Register = (on, options) => {
  maxLines = typeof options.maxLines === 'number' && options.maxLines >= 1 ? Math.round(options.maxLines) : 15

  on('ui.render', { component: 'AssistantMessage', surface: 'terminal' }, async ($, e, next) => {
    const commands = e.props.isSummary ? [] : commandsOf(e.props.text)
    if (commands.length === 0) return next(e)

    const row = await next(e)
    const { Box, Button, Text } = $.ui.resolve(e)
    const now = await $.clock.now()
    let isAnyRunning = false

    const items = await Promise.all(
      commands.map(async command => {
        const hash = await hashOf(command)
        const id = `${e.requestId}:${hash}`
        const { value: held } = await $.state.get({ ...runs, id })
        const isOrphan = held?.status === 'running' && !streams.has(id)
        const run: Run | undefined = isOrphan && held !== undefined ? { ...held, status: 'stopped' } : held
        const isRunning = run?.status === 'running'
        if (isRunning) isAnyRunning = true

        const [first = '', ...rest] = command.split('\n')
        const more = rest.length > 0 ? `  (+${rest.length} ${rest.length === 1 ? 'line' : 'lines'})` : ''
        const lines = run === undefined ? [] : linesOf(run.output)
        const shown = lines.slice(-maxLines)
        const hidden = lines.length - shown.length + (run !== undefined && run.cut > 0 ? 1 : 0)
        const took = run === undefined ? '' : seconds((run.endedAt ?? now) - run.startedAt)

        const status =
          run === undefined ? null : isRunning ? (
            <Text color="warning">running · {took}</Text>
          ) : run.status === 'failed' ? (
            <Text color="error">✗ could not run: {run.error ?? 'unknown error'}</Text>
          ) : run.status === 'stopped' ? (
            <Text color="warning">■ stopped · {took}{isOrphan ? ' (the mod reloaded)' : ''}</Text>
          ) : run.exitCode === 0 ? (
            <Text color="success">✓ exit 0 · {took}</Text>
          ) : (
            <Text color="error">✗ exit {run.exitCode ?? '?'} · {took}</Text>
          )

        return (
          <Box key={hash} flexDirection="column">
            <Box gap={1}>
              {isRunning ? (
                <Button key={`stop:${hash}`} label="■ Stop" onPress={() => stop($, id)} />
              ) : (
                <Button
                  key={`run:${hash}`}
                  label={run === undefined ? '▶ Run' : '↻ Run again'}
                  variant="primary"
                  onPress={() => start($, id, command)}
                />
              )}
              {run !== undefined && !isRunning && run.status !== 'failed' && (
                run.isSent === true ? (
                  <Text dimColor>sent to Claude</Text>
                ) : (
                  <Button key={`send:${hash}`} label="Send to Claude" onPress={() => send($, id)} />
                )
              )}
              <Text dimColor wrap="truncate-end">
                $ {first}
                {more}
              </Text>
            </Box>
            {run !== undefined && (
              <Box flexDirection="column" borderStyle="round" borderDimColor paddingX={1}>
                {hidden > 0 && <Text dimColor>… {hidden} earlier {hidden === 1 ? 'line' : 'lines'}</Text>}
                {shown.length === 0 && !isRunning && <Text dimColor>(no output)</Text>}
                {shown.map(line => (
                  <Text>{line === '' ? ' ' : line}</Text>
                ))}
                {status}
              </Box>
            )}
          </Box>
        )
      }),
    )

    // Reading tick subscribes the reply, so the timer's write moves the time.
    if (isAnyRunning) {
      await read($, tick)
      tickSoon($)
    }

    return (
      <Box flexDirection="column">
        {row}
        <Box flexDirection="column" paddingLeft={2}>
          {items}
        </Box>
      </Box>
    )
  })
}

