// One press of a command's Run button and what came of it.
export type Run = {
  command: string
  status: 'running' | 'done' | 'stopped' | 'failed'
  // The end of what the command wrote to stdout and stderr, as written.
  output: string
  // How many characters were cut from the front of `output`.
  cut: number
  exitCode?: number
  // Why the command could not run, for a failed one.
  error?: string
  startedAt: number
  endedAt?: number
  isSent?: boolean
}

declare module 'claude-code' {
  interface PluginState {
    'run-button': {
      // Keyed by the reply's row id and a hash of the command.
      runs: StateFamily<Run>
      // Bumped once a second while a command runs, so its time moves.
      tick: number
    }
  }
}
